using System;using System.IO;using System.IO.Compression;using System.Reflection;using System.Windows.Forms;using System.Diagnostics;using System.Net;using System.Threading;
class Setup {
 static string Quote(string value){return "\""+value+"\"";}
 [STAThread]static int Main(string[] args){bool silent=Array.IndexOf(args,"--silent")>=0;bool noShortcuts=Array.IndexOf(args,"--no-shortcuts")>=0;bool launch=Array.IndexOf(args,"--no-launch")<0;string target=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Programs","Fua Player");for(int i=0;i<args.Length-1;i++)if(args[i]=="--target")target=Path.GetFullPath(args[i+1]);
 try{if(!silent){var result=MessageBox.Show("Instalar o Fua Player em:\n"+target+"\n\nPreferências e backups existentes serão preservados.","Instalar Fua Player",MessageBoxButtons.OKCancel,MessageBoxIcon.Information);if(result!=DialogResult.OK)return 0;}
 try{var request=(HttpWebRequest)WebRequest.Create("http://127.0.0.1:8780/api/maintenance/shutdown");request.Method="POST";request.Headers["Origin"]="http://127.0.0.1:8780";request.ContentLength=0;request.Timeout=3000;using(var response=request.GetResponse()){}Thread.Sleep(1500);}catch{}
 Directory.CreateDirectory(target);string root=Path.GetFullPath(target).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;
 using(var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("fua-payload.zip"))using(var archive=new ZipArchive(stream,ZipArchiveMode.Read)){foreach(var entry in archive.Entries){string destination=Path.GetFullPath(Path.Combine(root,entry.FullName.Replace('/',Path.DirectorySeparatorChar)));if(!destination.StartsWith(root,StringComparison.OrdinalIgnoreCase))throw new Exception("Caminho inválido no instalador.");if(entry.FullName.EndsWith("/")){Directory.CreateDirectory(destination);continue;}Directory.CreateDirectory(Path.GetDirectoryName(destination));bool copied=false;for(int attempt=0;attempt<20&&!copied;attempt++){try{using(var input=entry.Open())using(var output=File.Create(destination))input.CopyTo(output);copied=true;}catch(IOException){if(attempt==19)throw;Thread.Sleep(500);}}}}
 if(!noShortcuts){Type shellType=Type.GetTypeFromProgID("WScript.Shell");dynamic shell=Activator.CreateInstance(shellType);foreach(string folder in new[]{Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),Environment.GetFolderPath(Environment.SpecialFolder.Programs)}){string link=Path.Combine(folder,"Fua Player.lnk");dynamic shortcut=shell.CreateShortcut(link);shortcut.TargetPath=Path.Combine(target,"FuaPlayer.exe");shortcut.WorkingDirectory=target;shortcut.IconLocation=Path.Combine(target,"fua-player-v2.ico")+",0";shortcut.Save();}}
 File.WriteAllText(Path.Combine(target,"installation.txt"),"Fua Player 1.0.0\r\nInstalado em "+DateTime.Now.ToString("s")+"\r\nDados pessoais: subpasta data.\r\n");if(!silent)MessageBox.Show("Fua Player instalado. O atalho foi criado na Área de Trabalho.","Fua Player");if(launch)Process.Start(new ProcessStartInfo(Path.Combine(target,"FuaPlayer.exe")){UseShellExecute=true,WorkingDirectory=target});return 0;
 }catch(Exception ex){if(!silent)MessageBox.Show(ex.Message,"Falha na instalação",MessageBoxButtons.OK,MessageBoxIcon.Error);else File.WriteAllText(Path.Combine(Path.GetTempPath(),"fua-setup-error.txt"),ex.ToString());return 1;}}
}
